import 'package:cloud_functions/cloud_functions.dart';
import '../models/cart_item.dart';
class FunctionService { final functions=FirebaseFunctions.instance; Future<void> saveCart(List<CartItem> items)=>functions.httpsCallable('updateCart').call({'items':items.map((x)=>x.toMap()).toList()}); Future<String> placeOrder({required List<CartItem> items,required Map<String,dynamic> address,required String paymentMethod,double discount=0,String? couponCode})async{final r=await functions.httpsCallable('placeOrder').call({'items':items.map((x)=>x.toMap()).toList(),'deliveryAddress':address,'paymentMethod':paymentMethod,'discount':discount,'couponCode':couponCode});return r.data['orderId'];} Future<double> validateCoupon(String code,double subtotal)async{final r=await functions.httpsCallable('validateCoupon').call({'code':code,'subtotal':subtotal});return (r.data['discount']??0).toDouble();}}
